213	    /// Normalizes a raw, provider-versioned model string (e.g. "claude-3-5-haiku-20241022",
214	    /// "gpt-4o-2024-08-06", "gemini-2.0-flash-001") down to one of this table's seeded
215	    /// canonical keys, by trying progressively shorter '-'-delimited prefixes of `model`
216	    /// against the set of model names actually present in `self.rates`, longest prefix first.
217	    /// Returns `None` when no prefix matches any seeded key -- callers must fall back to the
218	    /// CRIT-LUMEN-008 unrecognized-model behavior in that case.
219	    ///
220	    /// A small explicit alias table was considered instead, but seeded keys are themselves
221	    /// hyphen-delimited words (e.g. "claude-3-5-haiku") and every real-world date/version
222	    /// suffix observed (YYYYMMDD, YYYY-MM-DD, "-001", "-exp", "-32b-instruct") is just extra
223	    /// hyphen-delimited segments appended after the canonical name. Prefix-shortening solves
224	    /// all of them with one algorithm and needs no maintenance as new dated releases appear,
225	    /// whereas an alias table would need a new entry per new version string.
226	    fn normalize_model_key<'a>(&'a self, model: &'a str) -> Option<&'a str> {
227	        let parts: Vec<&str> = model.split('-').collect();
228	        for end in (1..=parts.len()).rev() {
229	            // Only accept this (shorter) candidate if every segment it would strip from the
230	            // tail is a safe version/date/scale marker -- never a segment that could denote a
231	            // genuinely different, differently-priced model (e.g. "mini", "lite", "nano").
232	            if !parts[end..].iter().all(|seg| Self::is_safe_strip_segment(seg)) {
233	                continue;
234	            }
235	            let candidate = &model[..Self::prefix_byte_len(&parts, end)];
236	            if self.rates.iter().any(|r| r.model == candidate) {
237	                return Some(candidate);
238	            }
239	        }
240	        None
241	    }
242	
243	    /// Whether a single '-'-delimited segment stripped from the tail of a raw model string is
244	    /// safe to discard when normalizing -- i.e. it can only ever denote a version, release
245	    /// date, or parameter-scale marker, never a genuinely different priced model name.
246	    ///
247	    /// Deliberately an ALLOWLIST of safe-to-strip patterns, not a denylist of known-bad words:
248	    /// a denylist can never be complete (new differently-priced model tiers are named
249	    /// constantly -- "mini", "nano", "flash-lite", ...), whereas the set of ways providers
250	    /// encode version/date/scale is small and closed.
251	    ///
252	    /// 1. Numeric-only segments ("20241022", "001", "0528", "4", "1") -- a bare number is never
253	    ///    a model-tier name.
254	    /// 2. Parameter-scale segments matching `^\d+[A-Za-z]$` ("32b", "70b") -- digits followed by
255	    ///    exactly one trailing letter denote model SIZE within the same family/price tier, not
256	    ///    a different-tier product name. Deliberately the strict single-trailing-letter form,
257	    ///    not a looser pattern that would also admit multi-token scale strings like "8x7b" --
258	    ///    no seeded key requires stripping that shape, so the stricter (safer) form is kept.
259	    /// 3. A small explicit allowlist of known non-differentiating tuning-suffix words.
260	    fn is_safe_strip_segment(segment: &str) -> bool {
261	        if !segment.is_empty() && segment.chars().all(|c| c.is_ascii_digit()) {
262	            return true;
263	        }
264	
265	        if let Some(last) = segment.chars().next_back() {
266	            if last.is_ascii_alphabetic() {
267	                let digits = &segment[..segment.len() - last.len_utf8()];
268	                if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
269	                    return true;
270	                }
271	            }
272	        }
273	
274	        // "fast"/"high" cover real observed request-time speed/effort variant suffixes
275	        // (gpt-5.6-terra-fast, gemini-3.7-flash-high) that carry no separately published price
276	        // for their provider. This is a deliberate, narrower judgment call than the rest of this
277	        // allowlist: Anthropic's "fast mode" IS a genuinely different, separately published
278	        // 2x-priced product (confirmed on platform.claude.com/docs/en/about-claude/pricing) --
279	        // but it is applied via a request parameter (`speed: "fast"`), never observed embedded
280	        // in a real `message.model` string this session. If a provider ever starts encoding
281	        // "-fast"/"-high" as part of the model name string for a genuinely different-priced
282	        // tier, this allowlist entry would silently mis-price it -- revisit if that's observed.
283	        matches!(segment, "exp" | "latest" | "preview" | "instruct" | "chat" | "fast" | "high")
284	    }
285	
286	    /// Byte length of the '-'-joined prefix consisting of the first `count` elements of
287	    /// `parts` (which were produced by splitting the original string on '-').
288	    fn prefix_byte_len(parts: &[&str], count: usize) -> usize {
289	        let joined_len: usize = parts[..count].iter().map(|p| p.len()).sum();
290	        // account for the (count - 1) '-' separators between the included parts
291	        joined_len + count.saturating_sub(1)
292	    }
293	
294	    /// Whether `model` -- after normalizing away any provider-versioning suffix -- matches at
295	    /// least one seeded row. Callers use this to distinguish "priced at 0.0 because this model
296	    /// genuinely has no cost for this token kind" from "priced at 0.0 because this model has no
297	    /// seeded pricing at all" (an unrecognized model), the latter of which must be surfaced to
298	    /// the user as an explicit unknown cost, not a silent (and previously wrong) dollar figure.
299	    pub fn is_recognized(&self, model: &str) -> bool {
300	        self.normalize_model_key(model).is_some()
301	    }
302	
303	    /// Looks up the rate for (model, tier, kind) whose effective window contains `as_of`.
304	    /// Returns 0.0, never a substituted rate from a different model, when the model string --
305	    /// after normalizing away any provider-versioning suffix -- matches no row at all: an
306	    /// earlier version of this function fell back to `claude-3-5-sonnet`'s rate for any
307	    /// unrecognized model, which silently mispriced every real session using a model outside
308	    /// the seeded set (confirmed against real local session data: every current Claude, GPT, and
309	    /// Gemini model in use collapsed onto Sonnet's rate). Callers that need to distinguish this
310	    /// case from a genuinely free/zero-rate row must call [`is_recognized`] separately -- this
311	    /// function's 0.0 return alone is ambiguous between the two. When the model IS recognized
312	    /// but has no row for this specific (tier, kind, as_of), also returns 0.0 (CRIT-LUMEN-161).
313	    ///
314	    /// [`is_recognized`]: Self::is_recognized
315	    ///
316	    /// When a specific `tier` is requested but `lookup_model` has no row matching that exact
317	    /// tier for this (kind, as_of), falls back to `lookup_model`'s own `tier: None` row for the
318	    /// same (kind, as_of) before giving up (Blocker #2). seed() pushes every row with
319	    /// `tier: None`, so without this fallback any caller that passes a real tier (e.g.
320	    /// CodexAdapter's captured `service_tier`) matched zero rows and silently priced at 0.0. A
321	    /// row that matches the exact requested tier still always wins over this fallback.
322	    pub fn rate_for(&self, model: &str, tier: Option<&str>, kind: TokenRateKind, as_of: DateTime<Utc>) -> f64 {
323	        let lookup_model = self.normalize_model_key(model).unwrap_or(model);
324	
325	        let matching = |wanted_tier: Option<&str>| {
326	            self.rates
327	                .iter()
328	                .filter(|r| {
329	                    r.model == lookup_model
330	                        && r.kind == kind
331	                        && r.tier.as_deref() == wanted_tier
332	                        && r.effective_from <= as_of
333	                        && r.effective_until.is_none_or(|until| as_of < until)
334	                })
335	                .max_by_key(|r| r.effective_from)
336	                .map(|r| r.rate_per_m)
337	        };
338	
339	        matching(tier).or_else(|| if tier.is_some() { matching(None) } else { None }).unwrap_or(0.0)
340	    }
341	}
