501	/// CRIT-LUMEN-160: a provider-reported cost (e.g. Claude Code's real costUSD field) passed as
502	/// `provided_cost_usd` must be stored verbatim on `TokenEconomics.provided_cost_usd`, and must
503	/// never override, blend with, or short-circuit the independently computed `total_cost_usd` --
504	/// the two fields exist to be compared for drift, not merged.
505	#[test]
506	fn test_provided_cost_usd_twin_field() {
507	    let pricing = PricingTable::seed();
508	    let as_of = Utc.with_ymd_and_hms(2024, 11, 1, 0, 0, 0).unwrap();
509	
510	    // 1,000,000 input tokens on claude-3-5-sonnet ($3.00/M) independently computes to $3.00,
511	    // which deliberately does NOT equal the provider-reported 4.20 supplied below.
512	    let turn = TurnPricingInput {
513	        usage: TurnTokenUsage {
514	            input_tokens: 1_000_000,
515	            cache_creation_tokens: 0,
516	            cache_read_tokens: 0,
517	            output_tokens: 0,
518	            reasoning_tokens: 0,
519	            cache_creation_1h_tokens: 0,
520	        },
521	        timestamp: as_of,
522	        tier: None,
523	    };
524	
525	    // (a) A provided cost that disagrees with the independently computed cost must be stored
526	    // verbatim in provided_cost_usd, and must NOT override or blend into total_cost_usd.
527	    let econ_with_provided =
528	        TokenEconomics::calculate(std::slice::from_ref(&turn), "claude-3-5-sonnet", &pricing, Some(4.20));
529	    assert_eq!(econ_with_provided.provided_cost_usd, Some(4.20));
530	    assert!(
531	        (econ_with_provided.total_cost_usd - 3.00).abs() < 1e-9,
532	        "total_cost_usd must remain the independently computed value (3.00), unaffected by the \
533	         disagreeing provided_cost_usd of 4.20"
534	    );
535	    assert!(
536	        (econ_with_provided.provided_cost_usd.unwrap() - econ_with_provided.total_cost_usd).abs() > 1e-9,
537	        "provided_cost_usd and total_cost_usd must be free to disagree -- they are compared for \
538	         drift, not merged"
539	    );
540	
541	    // (b) When no provided cost is supplied, provided_cost_usd must be None, not Some(0.0).
542	    let econ_without_provided =
543	        TokenEconomics::calculate(std::slice::from_ref(&turn), "claude-3-5-sonnet", &pricing, None);
544	    assert_eq!(econ_without_provided.provided_cost_usd, None);
545	}
